import React from 'react';
import { useTranslation } from 'react-i18next';

// --- DashboardHeader (Integrated into the Banner for cleaner styling) ---
// NOTE: I've removed the absolute positioning from the original component to fix the conflict.
// The menu button is now placed directly inside the main notification div.
const DashboardHeader = ({ onMenuClick, isEasyMode, t }) => ( 
    // This component will now just render the menu button
    <div style={{ 
        position: 'absolute', // Position the button relative to the parent banner div
        top: 0,
        right: 0,
        height: '100%',
        display: 'flex',
        alignItems: 'center',
        paddingRight: '10px',
        zIndex: 16, // Ensure it is above the banner text
    }}>
        <button
            onClick={onMenuClick}
            style={{ 
                padding: '8px',
                backgroundColor: 'transparent', 
                border: 'none', 
                borderRadius: '0', 
                cursor: 'pointer',
                fontSize: isEasyMode ? '36px' : '28px', 
                color: '#333',
                transition: 'color 0.2s',
            }}
            onMouseOver={e => e.currentTarget.style.color = '#1A73E8'} 
            onMouseOut={e => e.currentTarget.style.color = '#333'}
        >
            <span role="img" aria-label={t('general.menu')}>☰</span>
        </button>
    </div>
);
// --- END DashboardHeader ---


// --- Icon Component Modification (No changes needed, included for context) ---
const Icon = ({ name, emoji, isActive, onClick, isProminent, isEasyMode, keyName, color = '#1A73E8', bgColor = '#E8F0FE' }) => {
    
    // ... Icon logic and styling remain the same ...

    const isColored = isActive || isProminent; 
    let iconColor = color;
    let iconBgColor = '#E8F0FE'; // Default blue background
    
    if (keyName === "dashboard.emergency_info_card") {
        iconColor = '#DC3545';
        iconBgColor = '#FDE9E9';
    } else if (keyName === "medical_menu.access_card_short") {
        iconColor = '#1A73E8'; // Blue for Health Menu
        iconBgColor = '#E8F0FE';
    } else if (keyName === "dashboard.medical_history_card") {
        iconColor = '#17A2B8';
        iconBgColor = '#E8F7F9';
    }
    
    const baseFontSize = isEasyMode ? 32 : 18;
    let labelFontSize = baseFontSize;

    if (name && name.length > 12) {
        labelFontSize = isEasyMode ? 24 : 16;
    }


    return (
        <div 
            onClick={onClick} 
            style={{
                padding: '25px', 
                margin: '15px',
                border: `5px solid ${isColored ? iconColor : '#e0e0e0'}`,
                borderRadius: '15px', 
                width: '40%',
                textAlign: 'center',
                backgroundColor: isColored ? iconBgColor : '#ffffff',
                filter: isColored ? 'none' : 'grayscale(80%)',
                opacity: isColored ? 1 : 0.7, 
                cursor: 'pointer',
                boxShadow: isColored ? `0 8px 15px ${iconColor}4D` : '0 2px 5px rgba(0, 0, 0, 0.1)',
                transition: 'all 0.3s',
                fontSize: `${labelFontSize}px`, 
            }}
        >
            <span role="img" aria-label={name} style={{fontSize: isEasyMode ? '85px' : '40px', display: 'block', marginBottom: '10px'}}>{emoji}</span>
            <p style={{fontWeight: 'bold', color: '#333', margin: 0}}>{name}</p>
        </div>
    );
};
// --- END Icon Component Modification ---


function Dashboard({ isEasyMode, goToMedical, onMenuClick, goToEmergencyInfo }) { 
    const { t } = useTranslation();

    const showAppointmentNotification = true; 
    
    // Refined notification style (Now using padding and no margin)
    const notificationStyle = {
        padding: '15px 15px', // Reduced side padding for tighter fit
        backgroundColor: '#FFF3CD', // Soft yellow/orange alert background
        color: '#856404', 
        textAlign: 'center',
        cursor: 'pointer',
        fontSize: isEasyMode ? '24px' : '16px',
        fontWeight: 'bold',
        borderBottomLeftRadius: '10px', // Smoother border transitions
        borderBottomRightRadius: '10px',
        borderLeft: '5px solid #FFC107', 
        borderRight: '5px solid #FFC107',
        boxShadow: '0 4px 10px rgba(0,0,0,0.1)',
        position: 'relative', // Context for the menu button
        zIndex: 10,
        animation: 'blink-alert 1.8s infinite alternate', 
        display: 'flex', // Allow for better text/icon arrangement
        justifyContent: 'center',
        alignItems: 'center',
        width: '100%',
        boxSizing: 'border-box', // Ensure padding is included in the width
    };


    return (
        <div style={{ position: 'relative' }}>

            {/* NEW WRAPPER for the Top Section: This will handle the notification display */}
            <div style={{
                position: 'relative',
                width: '100%',
                marginBottom: '10px', // Space between the banner and the icons below
                padding: '0 15px', // Add the margin/padding for the banner on the wrapper
                boxSizing: 'border-box',
            }}>
                {/* RENDER THE NOTIFICATION BANNER */}
                {showAppointmentNotification && (
                    <div onClick={goToMedical} style={notificationStyle}>
                        <span role="img" aria-label={t('general.alert')} style={{marginRight: '10px'}}>🔔</span>
                        {t('dashboard.appointment_soon_alert')} {t('general.tap_here')}
                        
                        {/* THE HEADER (MENU BUTTON) IS NOW INSIDE THE BANNER */}
                        <DashboardHeader onMenuClick={onMenuClick} isEasyMode={isEasyMode} t={t} />
                    </div>
                )}
            </div>

            {/* MAIN ICON GRID (Adjusted paddingTop since the banner is now handled by the wrapper) */}
            <div style={{ 
                display: 'flex', 
                flexWrap: 'wrap', 
                justifyContent: 'center', 
                paddingTop: showAppointmentNotification ? '0px' : '40px', // Adjusted to 0
                paddingBottom: '40px' 
            }}>
                
                {/* Icons... */}
                <Icon 
                    name={t('medical_menu.access_card_short')} 
                    emoji="🏥" 
                    isActive={true} 
                    onClick={goToMedical} 
                    isEasyMode={isEasyMode}
                    keyName={'medical_menu.access_card_short'} 
                />
                
                <Icon 
                    name={t('dashboard.emergency_info_card')} 
                    emoji="🆘" 
                    isProminent={true} 
                    isActive={false} 
                    onClick={goToEmergencyInfo} 
                    isEasyMode={isEasyMode}
                    keyName={'dashboard.emergency_info_card'} 
                />
                
                <Icon 
                    name={t('dashboard.medical_history_card')} 
                    emoji="📜" 
                    isProminent={true} 
                    isActive={false} 
                    onClick={() => console.log('Medical History page route needed.')}
                    isEasyMode={isEasyMode}
                    keyName={'dashboard.medical_history_card'} 
                />
                
                <div style={{ width: '40%', margin: '15px', visibility: 'hidden' }}></div>
            </div>

            {/* CSS Animation */}
            <style jsx>{`
                @keyframes blink-alert {
                    0% { 
                        opacity: 1; 
                        box-shadow: 0 4px 15px rgba(255, 193, 7, 0.6); 
                        border-color: #FFC107;
                    }
                    50% { 
                        opacity: 0.8; 
                        box-shadow: 0 4px 5px rgba(0,0,0,0.1); 
                        border-color: #FFEB3B;
                    }
                    100% { 
                        opacity: 1; 
                        box-shadow: 0 4px 15px rgba(255, 193, 7, 0.6); 
                        border-color: #FFC107;
                    }
                }
            `}</style>
        </div>
    );
}

export default Dashboard;
